    "https://play.google.com/store/apps/developer?id=Insheera"
  ],
  "contactPoint": {
    "@type": "ContactPoint",
    "contactType": "customer service",
    "email": "info.insheera@gmail.com"
  },
  "makesOffer": [
    {
      "@type": "SoftwareApplication",
      "name": "Al Muslim",
      "description": "All-in-one Islamic app featuring Quran, Hadith, prayer times, Qibla compass, and Islamic calendar.",
      "applicationCategory": "LifestyleApplication",
      "operatingSystem": ["Android"]
    }
  ]
}

head.b:skin:

  /* CSS Variables for Dark Mode */
  :root {
    --primary-color: #2c5530;
    --secondary-color: #4a7c59;
    --accent-color: #81c784;
    --text-color: #2c2c2c;
    --bg-color: #ffffff;
    --card-bg: #f8f9fa;
    --border-color: #e0e0e0;
    --shadow: rgba(0,0,0,0.1);
    --transition: all 0.3s ease;
  }

  [data-theme="dark"] {
    --text-color: #e0e0e0;
    --bg-color: #1a1a1a;
    --card-bg: #2d2d2d;
    --border-color: #404040;
    --shadow: rgba(255,255,255,0.1);
  }

  /* Reset and Base Styles */
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--bg-color);
    transition: var(--transition);
  }

  /* Header Styles */
  .site-header {
    background: var(--bg-color);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 1000;
    transition: var(--transition);
  }

  .header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 70px;
  }

  .logo {
    display: flex;
    align-items: center;
    text-decoration: none;
    color: var(--text-color);
    font-weight: 700;
    font-size: 24px;
  }

  .logo img {
    height: 40px;
    margin-right: 10px;
  }

  .main-nav {
    display: flex;
    list-style: none;
    align-items: center;
    gap: 30px;
  }

  .main-nav a {
    text-decoration: none;
    color: var(--text-color);
    font-weight: 500;
    transition: var(--transition);
    position: relative;
  }

  .main-nav a:hover {
    color: var(--primary-color);
  }

  .main-nav a::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--primary-color);
    transition: width 0.3s ease;
  }

  .main-nav a:hover::after {
    width: 100%;
  }

  /* Dark Mode Toggle */
  .theme-toggle {
    background: none;
    border: 2px solid var(--border-color);
    border-radius: 20px;
    padding: 8px 12px;
    cursor: pointer;
    color: var(--text-color);
    transition: var(--transition);
  }

  .theme-toggle:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
  }

  /* Mobile Menu */
  .mobile-menu-toggle {
    display: none;
    background: none;
    border: none;
    font-size: 24px;
    color: var(--text-color);
    cursor: pointer;
  }

  /* Hero Section */
  .hero-section {
    background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
    color: white;
    padding: 100px 0;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .hero-section::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000"><polygon fill="rgba(255,255,255,0.1)" points="0,1000 1000,0 1000,1000"/></svg>');
    background-size: cover;
  }

  .hero-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    position: relative;
    z-index: 1;
  }

  .hero-title {
    font-size: 3.5rem;
    font-weight: 700;
    margin-bottom: 20px;
    opacity: 0;
    animation: fadeInUp 1s ease 0.2s forwards;
  }

  .hero-subtitle {
    font-size: 1.3rem;
    margin-bottom: 30px;
    opacity: 0.9;
    opacity: 0;
    animation: fadeInUp 1s ease 0.4s forwards;
  }

  .hero-description {
    font-size: 1.1rem;
    max-width: 600px;
    margin: 0 auto 40px;
    opacity: 0;
    animation: fadeInUp 1s ease 0.6s forwards;
  }

  .cta-buttons {
    display: flex;
    justify-content: center;
    gap: 20px;
    margin-top: 40px;
    opacity: 0;
    animation: fadeInUp 1s ease 0.8s forwards;
  }

  .btn {
    display: inline-flex;
    align-items: center;
    padding: 15px 30px;
    border-radius: 50px;
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
    border: 2px solid transparent;
  }

  .btn-primary {
    background: white;
    color: var(--primary-color);
  }

  .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(0,0,0,0.15);
  }

  .btn-secondary {
    background: transparent;
    color: white;
    border-color: white;
  }

  .btn-secondary:hover {
    background: white;
    color: var(--primary-color);
  }

  /* Apps Section */
  .apps-section {
    padding: 100px 0;
    background: var(--card-bg);
  }

  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
  }

  .section-title {
    text-align: center;
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--primary-color);
    margin-bottom: 20px;
  }

  .section-subtitle {
    text-align: center;
    font-size: 1.2rem;
    color: var(--text-color);
    margin-bottom: 60px;
    opacity: 0.8;
  }

  .apps-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 40px;
    margin-top: 60px;
  }

  .app-card {
    background: var(--bg-color);
    border-radius: 20px;
    padding: 40px;
    text-align: center;
    box-shadow: 0 10px 30px var(--shadow);
    transition: var(--transition);
    border: 1px solid var(--border-color);
  }

  .app-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 50px var(--shadow);
  }

  .app-icon {
    width: 120px;
    height: 120px;
    margin: 0 auto 30px;
    background: var(--accent-color);
    border-radius: 25px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 48px;
    color: white;
  }

  .app-icon img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 20px;
	box-shadow: 
      0 4px 8px rgba(0, 0, 0, 0.1),
      0 8px 16px rgba(0, 0, 0, 0.1);
  }

  .app-title {
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--primary-color);
    margin-bottom: 15px;
  }

  .app-description {
    color: var(--text-color);
    margin-bottom: 30px;
    line-height: 1.7;
  }

  .app-features {
    list-style: none;
    text-align: left;
    margin-bottom: 30px;
  }

  .app-features li {
    padding: 8px 0;
    position: relative;
    padding-left: 25px;
  }

  .app-features li::before {
    content: '\2705';
    position: absolute;
    left: 0;
    color: var(--accent-color);
    font-weight: bold;
  }

  /* Buttons Container */
  .download-buttons {
    display: flex;
    justify-content: center;
    gap: 15px;
    flex-wrap: wrap;
  }

  /* Text Button */
  .download-btn {
    display: inline-flex;
    align-items: center;
    padding: 12px 20px;
    background: var(--primary-color);
    color: white;
    text-decoration: none;
    border-radius: 10px;
    transition: var(--transition);
    font-weight: 500;
  }

  .download-btn:hover {
    background: var(--secondary-color);
    transform: translateY(-2px);
  }

  /* Image Button */
  .img-download-btn {
    display: inline-flex;
    align-items: center;
    text-decoration: none;
    transition: var(--transition);
    /* No padding or background */
  }

  .img-download-btn:hover {
    transform: translateY(-2px);
  }

  .playstore-img {
    height: 68px;
    display: block;
  }

  /* Stats Section */
  .stats-section {
    padding: 80px 0;
    background: var(--primary-color);
    color: white;
  }

  .stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 40px;
  }

  .stat-item {
    text-align: center;
  }

  .stat-number {
    font-size: 3rem;
    font-weight: 700;
    margin-bottom: 10px;
    color: var(--accent-color);
  }

  .stat-label {
    font-size: 1.1rem;
    opacity: 0.9;
  }

  /* About Section */
  .about-section {
    padding: 100px 0;
  }

  .about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
  }

  .about-text h2 {
    font-size: 2.5rem;
    color: var(--primary-color);
    margin-bottom: 20px;
  }

  .about-text p {
    margin-bottom: 20px;
    line-height: 1.8;
    color: var(--text-color);
  }

  .about-image {
    text-align: center;
  }

  .about-image img {
    max-width: 100%;
    border-radius: 20px;
    box-shadow: 0 20px 50px var(--shadow);
  }

  /* Contact Form Start */
  .contact-form-title {
    color: var(--primary-color, #2d89ef);
    font-size: 1.6rem;
    font-weight: 700;
    margin-bottom: 10px;
  }

  .contact-section {
    padding: 100px 0;
    background: var(--card-bg);
  }

  .contact-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
  }

  .contact-info h3 {
    color: var(--primary-color);
    font-size: 1.5rem;
    margin-bottom: 20px;
  }

  .contact-item {
    display: flex;
    align-items: center;
    margin-bottom: 20px;
  }

  .contact-item span {
    margin-right: 15px;
    color: var(--accent-color);
    font-size: 20px;
  }

  /* Main form container */
  .contact-form-widget {
    background: var(--bg-color);
    padding: 40px;
    border-radius: 20px;
    box-shadow: 0 10px 30px var(--shadow);
  }

  /* Form fields */
  .contact-form-widget label {
    display: block;
    margin-bottom: 8px;
    font-weight: 600;
    color: var(--text-color);
  }

  .contact-form-name,
  .contact-form-email,
  .contact-form-email-message {
    width: 100%;
    padding: 12px 15px;
    border: 2px solid var(--border-color);
    border-radius: 10px;
    background: var(--bg-color);
    color: var(--text-color);
    transition: var(--transition);
    margin-bottom: 25px;
    box-sizing: border-box;
  }

  .contact-form-name:focus,
  .contact-form-email:focus,
  .contact-form-email-message:focus {
    outline: none;
    border-color: var(--primary-color);
  }

  /* Submit button */
  .contact-form-button {
    background-color: var(--primary-color);
    color: #fff;
    border: none;
    padding: 12px 20px;
    border-radius: 10px;
    cursor: pointer;
    font-weight: bold;
    font-size: 14px;
    transition: var(--transition);
  }

  .contact-form-button:hover {
    background-color: #1861c2;
  }

  /* Success & error messages */
  .contact-form-success-message {
    color: green;
    font-size: 14px;
    margin-top: 10px;
    text-align: center;
  }

  .contact-form-error-message {
    color: red;
    font-size: 14px;
    margin-top: 10px;
    text-align: center;
  }
  /* Contact Form End */


  /* Footer */
  .site-footer {
    background: var(--primary-color);
    color: white;
    padding: 60px 0 30px;
  }

  .footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 40px;
    margin-bottom: 40px;
  }

  .footer-section h3 {
    margin-bottom: 20px;
    color: var(--accent-color);
  }

  .footer-section p,
  .footer-section a {
    color: rgba(255,255,255,0.8);
    text-decoration: none;
    line-height: 1.8;
  }

  .footer-section a:hover {
    color: white;
  }

  .social-links {
    display: flex;
    gap: 15px;
    margin-top: 20px;
  }

  .social-links a {
    width: 40px;
    height: 40px;
    background: rgba(255,255,255,0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    transition: var(--transition);
  }

  .social-links a:hover {
    background: var(--accent-color);
  }

  .footer-bottom {
    text-align: center;
    padding-top: 30px;
    border-top: 1px solid rgba(255,255,255,0.1);
    color: rgba(255,255,255,0.8);
  }

  /* Blog Styles */
  .blog-post {
    background: var(--bg-color);
    border-radius: 15px;
    overflow: hidden;
    box-shadow: 0 5px 20px var(--shadow);
    margin-bottom: 30px;
    transition: var(--transition);
  }

  .blog-post:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 30px var(--shadow);
  }

  .post-thumbnail {
    height: 250px;
    background: var(--accent-color);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 24px;
  }

  .post-content {
    padding: 30px;
  }

  .post-title {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary-color);
    margin-bottom: 15px;
  }

  .post-title a {
    color: inherit;
    text-decoration: none;
  }

  .post-meta {
    color: var(--text-color);
    font-size: 0.9rem;
    margin-bottom: 15px;
    opacity: 0.7;
  }

  .post-excerpt {
    color: var(--text-color);
    line-height: 1.6;
    margin-bottom: 20px;
  }

  .read-more {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
  }

  .read-more:hover {
    color: var(--secondary-color);
  }

  /* Breadcrumbs */
  .breadcrumb {
    background: var(--card-bg);
    padding: 15px 0;
    margin-bottom: 30px;
  }

  .breadcrumb-list {
    display: flex;
    list-style: none;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
  }

  .breadcrumb-item {
    color: var(--text-color);
  }

  .breadcrumb-item a {
    color: var(--primary-color);
    text-decoration: none;
  }

  .breadcrumb-item:not(:last-child)::after {
    content: '›';
    margin: 0 10px;
    color: var(--text-color);
    opacity: 0.5;
  }

  /* Animations */
  @keyframes fadeInUp {
    from {
      opacity: 0;
      transform: translateY(30px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .fade-in-up {
    opacity: 0;
    animation: fadeInUp 0.8s ease forwards;
  }

  /* Responsive Design */
  @media (max-width: 768px) {
    .main-nav {
      display: none;
      position: absolute;
      top: 100%;
      left: 0;
      right: 0;
      background: var(--bg-color);
      flex-direction: column;
      padding: 20px;
      box-shadow: 0 5px 15px var(--shadow);
    }

    .main-nav.active {
      display: flex;
    }

    .mobile-menu-toggle {
      display: block;
    }

    .hero-title {
      font-size: 2.5rem;
    }

    .hero-subtitle {
      font-size: 1.1rem;
    }

    .cta-buttons {
      flex-direction: column;
      align-items: center;
    }

    .apps-grid {
      grid-template-columns: 1fr;
    }

    .about-content {
      grid-template-columns: 1fr;
    }

    .contact-grid {
      grid-template-columns: 1fr;
    }

    .stats-grid {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @media (max-width: 480px) {
    .hero-title {
      font-size: 2rem;
    }

    .section-title {
      font-size: 2rem;
    }

    .apps-grid {
      grid-template-columns: 1fr;
      gap: 20px;
    }

    .app-card {
      padding: 30px 20px;
    }

    .stats-grid {
      grid-template-columns: 1fr;
    }
  }

  /* Print Styles */
  @media print {
    .site-header,
    .site-footer,
    .cta-buttons,
    .download-buttons {
      display: none;
    }

    body {
      color: #000;
      background: #fff;
    }
  }

body.script:
//

// Theme Toggle Functionality
function toggleTheme() {
  const body = document.body;
  const themeToggle = document.getElementById('themeToggle');
  const currentTheme = localStorage.getItem('theme') || 'light';
  const newTheme = currentTheme === 'light' ? 'dark' : 'light';

  body.setAttribute('data-theme', newTheme);
  localStorage.setItem('theme', newTheme);
  themeToggle.textContent = newTheme === 'dark' ? '☀️' : '🌙';
}

// Load saved theme
document.addEventListener('DOMContentLoaded', function() {
  const savedTheme = localStorage.getItem('theme') || 'light';
  const themeToggle = document.getElementById('themeToggle');

  document.body.setAttribute('data-theme', savedTheme);
  if (themeToggle) {
    themeToggle.textContent = savedTheme === 'dark' ? '☀️' : '🌙';
  }

  // Update current year in footer
  const yearElement = document.getElementById('currentYear');
  if (yearElement) {
    yearElement.textContent = new Date().getFullYear();
  }
});

// Mobile Menu Toggle
function toggleMobileMenu() {
  const nav = document.querySelector('.main-nav');
  nav.classList.toggle('active');
}

// Smooth scrolling for anchor links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
  anchor.addEventListener('click', function (e) {
    e.preventDefault();
    const target = document.querySelector(this.getAttribute('href'));
    if (target) {
      target.scrollIntoView({
        behavior: 'smooth',
        block: 'start'
      });
    }
  });
});

// Animation on scroll
const observerOptions = {
  threshold: 0.1,
  rootMargin: '0px 0px -50px 0px'
};

const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('fade-in-up');
    }
  });
}, observerOptions);

// Observe elements for animation
document.querySelectorAll('.app-card, .stat-item, .blog-post').forEach(el => {
  observer.observe(el);
});

// Header scroll effect
let lastScrollTop = 0;
const header = document.querySelector('.site-header');

window.addEventListener('scroll', () => {
  const scrollTop = window.pageYOffset || document.documentElement.scrollTop;

  if (scrollTop > lastScrollTop && scrollTop > 100) {
    // Scrolling down
    header.style.transform = 'translateY(-100%)';
  } else {
    // Scrolling up
    header.style.transform = 'translateY(0)';
  }

  lastScrollTop = scrollTop;
});

// Form validation
document.querySelectorAll('form').forEach(form => {
  form.addEventListener('submit', function(e) {
    const requiredFields = form.querySelectorAll('[required]');
    let isValid = true;

    requiredFields.forEach(field => {
      if (!field.value.trim()) {
        isValid = false;
        field.style.borderColor = '#e74c3c';
        field.placeholder = 'This field is required';
      } else {
        field.style.borderColor = '';
      }
    });

    if (!isValid) {
      e.preventDefault();
      alert('Please fill in all required fields.');
    }
  });
});

// Lazy loading for images
if ('IntersectionObserver' in window) {
  const imageObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const img = entry.target;
        if (img.dataset.src) {
          img.src = img.dataset.src;
          img.removeAttribute('data-src');
          observer.unobserve(img);
        }
      }
    });
  });

  document.querySelectorAll('img[data-src]').forEach(img => {
    imageObserver.observe(img);
  });
}

// SEO and performance optimizations
// Preload critical fonts
const fontLink = document.createElement('link');
fontLink.rel = 'preload';
fontLink.as = 'font';
fontLink.type = 'font/woff2';
fontLink.crossOrigin = 'anonymous';
document.head.appendChild(fontLink);

// Service Worker registration (if available)
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch(() => {
      // Service worker not available, continue normally
    });
  });
}

//
